class Allocator {
  private mem: number[];

  constructor(n: number) {
    this.mem = new Array(n).fill(0);
  }

  allocate(size: number, owner: number): number {
    let run = 0;
    for (let i = 0; i < this.mem.length; i++) {
      run = this.mem[i] === 0 ? run + 1 : 0;
      if (run === size) {
        const start = i - size + 1;
        for (let k = start; k <= i; k++) this.mem[k] = owner;
        return start;
      }
    }
    return -1;
  }

  release(owner: number): number {
    let freed = 0;
    for (let i = 0; i < this.mem.length; i++)
      if (this.mem[i] === owner) { this.mem[i] = 0; freed++; }
    return freed;
  }
}

