class Allocator {
  private free: [number, number][]; // sorted, disjoint [start, end)
  private blocks = new Map<number, [number, number][]>();

  constructor(n: number) {
    this.free = [[0, n]];
  }

  allocate(size: number, owner: number): number {
    for (let k = 0; k < this.free.length; k++) {
      const [s, e] = this.free[k];
      if (e - s < size) continue;
      if (e - s === size) this.free.splice(k, 1);
      else this.free[k] = [s + size, e];
      if (!this.blocks.has(owner)) this.blocks.set(owner, []);
      this.blocks.get(owner)!.push([s, s + size]);
      return s;
    }
    return -1;
  }

  release(owner: number): number {
    const mine = this.blocks.get(owner);
    if (!mine) return 0;
    this.blocks.delete(owner);
    let freed = 0;
    for (const [s, e] of mine) freed += e - s;
    const all = [...this.free, ...mine].sort((a, b) => a[0] - b[0]);
    const merged: [number, number][] = [];
    for (const [s, e] of all) {
      const last = merged[merged.length - 1];
      if (last && last[1] === s) last[1] = e; // touching intervals join
      else merged.push([s, e]);
    }
    this.free = merged;
    return freed;
  }
}

