            if e - s < size:
                continue
            if e - s == size:
                self.free.pop(k)
            else:
                self.free[k] = [s + size, e]
            self.blocks[owner].append([s, s + size])
            return s
        return -1

    def release(self, owner: int) -> int:
        mine = self.blocks.pop(owner, [])
        if not mine:
            return 0
        freed = sum(e - s for s, e in mine)
        merged = []
        for s, e in sorted(self.free + mine):
            if merged and merged[-1][1] == s:  # touching intervals join
                merged[-1][1] = e
            else:
                merged.append([s, e])
        self.free = merged
        return freed

